const input = $input.first()?.json ?? {};
const body = input.body ?? input;

return [{
  json: {
    config: {
      companyName: body.companyName || 'ABM Solutions Demo',
      demoMode: body.demoMode !== false
    },
    payload: body
  }
}];

const d=$input.first().json,r=d.request;
const stages=[{stage:'manager',required:r.amount>=500,approved:!!r.managerApproved},{stage:'finance',required:r.amount>=2500,approved:!!r.financeApproved}];
const failed=stages.find(s=>s.required&&!s.approved);
const status=failed?'rejected':stages.some(s=>s.required)?'approved':'auto_approved';
return [{json:{...d,result:{requestId:r.requestId,status,stages,auditTrail:stages.map(s=>({stage:s.stage,required:s.required,approved:s.approved,checkedAt:new Date().toISOString()})),reason:failed?`Rejected at ${failed.stage} approval`:'All required approvals passed'}}}];
